package com.rpb.reservation.wallet.marketing;
import com.rpb.reservation.common.scope.StoreScope;
import com.rpb.reservation.tenant.value.TenantId;
import com.rpb.reservation.wallet.api.*;
import com.rpb.reservation.wallet.application.*;
import com.rpb.reservation.wallet.domain.WalletException;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.any;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
/** Request contract and capability negotiation before any money use case is invoked. */
class WalletStaffMarketingApiTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),account=UUID.randomUUID(),source=UUID.randomUUID();
 final StoreScope scope=new StoreScope(new TenantId(tenant),store);
 final CurrentActor actor=new CurrentActor(tenant,UUID.randomUUID(),"staff",Set.of(),Set.of("wallet.topup.create","wallet.collection.confirm","wallet.refund.manage"),Set.of(store));
 WalletApiIdentity identity;WalletTopupService topups;WalletRefundService refunds;MockMvc mvc;
 String staff(){return "/api/v1/stores/"+store+"/wallet";}
 @BeforeEach void setup(){identity=mock(WalletApiIdentity.class);topups=mock(WalletTopupService.class);refunds=mock(WalletRefundService.class);when(identity.staff()).thenReturn(actor);when(identity.scope(tenant,store)).thenReturn(scope);mvc=MockMvcBuilders.standaloneSetup(new WalletStaffController(identity,null,topups,null,null,refunds,null,null)).setControllerAdvice(new WalletErrorAdvice()).addFilters(new WalletRequestSecurityFilter()).build();}
 @Test void permitsExactlyOneServerQuoteOrOrdinaryAmountAndPreservesDecimalText()throws Exception{UUID quote=UUID.randomUUID();mvc.perform(post(staff()+"/topups").header("X-RPB-Wallet","1").contentType("application/json").content("{\"accountId\":\""+account+"\",\"quoteId\":\""+quote+"\",\"idempotencyKey\":\"quoted\"}")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","private, no-store"));verify(topups).create(scope,actor,new WalletCommands.TopupCreate(account,null,null,"quoted",quote));mvc.perform(post(staff()+"/topups").header("X-RPB-Wallet","1").contentType("application/json").content("{\"accountId\":\""+account+"\",\"amount\":\"100.00\",\"channel\":\"cash\",\"idempotencyKey\":\"ordinary\"}")).andExpect(status().isOk());verify(topups).create(scope,actor,new WalletCommands.TopupCreate(account,"100.00","cash","ordinary"));}
 @Test void rejectsGiftQuantityArraysIdentityUnknownFieldsAndMixedQuoteWithoutCallingMoney()throws Exception{for(String extra:List.of("\"gift\":10","\"quantity\":2","\"offers\":[]","\"bonusCents\":1000","\"customerId\":\""+account+"\"","\"surprise\":true","\"quoteId\":\""+UUID.randomUUID()+"\"")){mvc.perform(post(staff()+"/topups").header("X-RPB-Wallet","1").contentType("application/json").content("{\"accountId\":\""+account+"\",\"amount\":\"100.00\",\"channel\":\"cash\",\"idempotencyKey\":\"key\","+extra+"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("WALLET_TOPUP_SINGLE_OFFER_REQUIRED"));}mvc.perform(post(staff()+"/topups").header("X-RPB-Wallet","1").contentType("application/json").content("{\"accountId\":\""+account+"\",\"amount\":100,\"channel\":\"cash\",\"idempotencyKey\":\"key\"}")).andExpect(status().isBadRequest());verifyNoInteractions(topups,refunds);}
 @Test void allFourMoneyEndpointsRequireComponentsCapability()throws Exception{for(String suffix:List.of("/topups/"+source+"/confirm","/refunds","/refunds/"+source+"/confirm","/refunds/"+source+"/cancel")){for(String model:List.of("","legacy")){mvc.perform(post(staff()+suffix).header("X-RPB-Wallet","1").header("X-RPB-Wallet-Model",model).contentType("application/json").content("{}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("WALLET_CLIENT_UPGRADE_REQUIRED"));}}verifyNoInteractions(topups,refunds);}
 @Test void missingStaffIdentityWinsOverMissingModelOnAllFourEndpoints()throws Exception{when(identity.staff()).thenThrow(new WalletException("WALLET_UNAUTHENTICATED",401,"请先登录"));for(String suffix:List.of("/topups/"+source+"/confirm","/refunds","/refunds/"+source+"/confirm","/refunds/"+source+"/cancel")){mvc.perform(post(staff()+suffix).header("X-RPB-Wallet","1").contentType("application/json").content("{}")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("WALLET_UNAUTHENTICATED"));}verifyNoInteractions(topups,refunds);}
 @Test void validCapabilityStillRequiresRefundVersionAndDelegatesConfirmCancel()throws Exception{mvc.perform(post(staff()+"/refunds").header("X-RPB-Wallet","1").header("X-RPB-Wallet-Model","components-v2").contentType("application/json").content("{}")).andExpect(status().isBadRequest());verifyNoInteractions(refunds);mvc.perform(post(staff()+"/topups/"+source+"/confirm").header("X-RPB-Wallet","1").header("X-RPB-Wallet-Model","components-v2").contentType("application/json").content("{}")).andExpect(status().isOk());verify(topups).confirm(eq(scope),eq(actor),eq(source),any());mvc.perform(post(staff()+"/refunds/"+source+"/confirm").header("X-RPB-Wallet","1").header("X-RPB-Wallet-Model","components-v2").contentType("application/json").content("{\"partId\":\""+account+"\",\"receiptReference\":\"ref\",\"idempotencyKey\":\"confirm\"}")).andExpect(status().isOk());verify(refunds).confirmPart(scope,actor,source,account,"ref","confirm");mvc.perform(post(staff()+"/refunds/"+source+"/cancel").header("X-RPB-Wallet","1").header("X-RPB-Wallet-Model","components-v2").contentType("application/json").content("{\"idempotencyKey\":\"cancel\"}")).andExpect(status().isOk());verify(refunds).cancel(scope,actor,source,"cancel");}
 @Test void legacyListEndpointsAreRetiredButOperationsRemain()throws Exception{for(String path:List.of("/topups","/bills","/refunds"))mvc.perform(get(staff()+path)).andExpect(status().isMethodNotAllowed());verifyNoInteractions(topups,refunds);}
}
